/**
 * Choose This Day
 * ---------------
 * Joshua gathers the people at Shechem and says: choose this day whom you will serve, but as for me and my house, we will serve the Lord. Stage: a great stone under the oaks of Shechem, an old man speaking, the people answering; a covenant renewed, the sun setting on a lifetime.
 *
 * Palette 0x2d1a0e → 0x060402 · light: dawn · hero: pillar
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./joshua-kit.js.
 */

import { THREE, createScene, house, pillar, person, crowd } from './joshua-kit.js';

const BG = 0x2d1a0e;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 4039296758, bg: BG, fogNear: 55, fogFar: 220 });

    /* light — dawn */
    W.lights({ sky: 0x9ab4d0, gnd: 0x5a5a52, hemi: 0.75, sun: 0xffd9a0, sunI: 0.95, sunPos: [-45, 16, 26] });

    W.disc([-58, 30, -145], 9, 0xffd9a0);
    W.disc([-58, 30, -155], 16, 0xffb060, 0.22);
    W.stars(60, 150, [0xcfd8e8, 0xbfd0e0], 0.55);
    const clouds = W.grp(group, [0, 0, 0], { name: 'cloud_bank' });
    [[-60, 34, -120, 24], [10, 40, -135, 30], [70, 33, -125, 22]].forEach(([x, y, z, s]) => {
        W.add(clouds, W.G('ico', 1, 1), W.mat(0xd8c8b8, { opacity: 0.5 }), [x, y, z], { s: [s, s * 0.24, s * 0.5] });
    });
    W.backdrop(clouds);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* house: mud-brick walls, flat roof, door */
    house(W, group, -18, 0, -20, 1.0 + W.r() * 0.3, { mud: 0x060402 });
    house(W, group, -27, 0, -15, 0.8 + W.r() * 0.3, { mud: 0x060402 });

    /* hero: the standing stone */
    pillar(W, group, 0, 0, 0, 1.15, { stone: 0x060402 });
    W.disc([0, 6, -12], 5, 0x3b2212, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0x2d1a0e, ry: -0.09, s: 1.19 });
    person(W, group, [4.5, 0, 6], { robe: 0x060402, ry: -0.33, s: 1.03 });
    person(W, group, [1, 0, -5], { robe: 0x8a6a44, ry: -0.62, s: 1.02 });
    /* crowd: the people of the story */
    crowd(W, group, 0, 16, 24, 70, 44, [0x2d1a0e, 0x060402, 0x8a6a44, 0x6a4a30, 0xc8b088, 0x5a4a6a]);

    return W.finish();
}

export default { build };
